<template>
  <section class="ai-personalized-section" aria-labelledby="ai-title">
    <div class="ai-shell">
      <div class="ai-heading"><div><span class="eyebrow">A COMPANION FOR THE NEXT STEP</span><h2 id="ai-title">AI 下一步建议</h2><p>它读过你的学习记录，帮你把“接下来做什么”说得更具体。</p></div><span class="ai-badge">AI 学习助手</span></div>

      <div v-if="userStore.loading" class="ai-state">正在读取你的学习状态...</div>
      <div v-else-if="!userStore.isLoggedIn" class="ai-login-state"><div class="assistant-avatar">AI</div><div><strong>登录后，让建议真正属于你</strong><p>同步错题、阅读和创作记录，解锁复习推荐、学习推荐与 AI 学习分析报告。</p></div><button class="ai-button" @click="$router.push('/login')">登录查看 <span>↗</span></button></div>
      <div v-else-if="error" class="ai-state ai-error"><span>{{ error }}</span><button class="ai-button" @click="fetchData">重新加载</button></div>
      <div v-else class="ai-content">
        <div class="assistant-brief"><div class="assistant-avatar">AI</div><div class="brief-copy"><span class="brief-label">{{ getGreetingText() }}，这是我建议你现在做的事</span><strong>{{ nextAction.title }}</strong><p>{{ nextAction.reason }}</p></div><button class="ai-button primary" @click="nextAction.poemId ? navigateToDetail(nextAction.poemId) : $router.push(nextAction.path)">{{ nextAction.action }} <span>↗</span></button></div>

        <div class="recommendation-grid">
          <article class="recommendation-panel"><div class="panel-heading"><div><span class="panel-icon">复</span><div><h3>复习推荐</h3><p>把快要忘记的，及时捡回来</p></div></div><button @click="$router.push('/challenge/review')">错题本 ↗</button></div><div v-if="reviewLoading" class="panel-state">AI 正在读取你的复习节奏...</div><div v-else-if="reviewItems.length === 0" class="panel-state">暂时没有需要优先复习的诗词。</div><button v-for="(item, index) in reviewItems.slice(0, 3)" :key="item.poem_id || index" class="recommend-row" @click="navigateToDetail(item.poem_id)"><span class="row-index">0{{ index + 1 }}</span><span class="row-copy"><strong>{{ item.title }}</strong><small>{{ item.author }} · {{ item.reason || '根据最近的学习记录推荐' }}</small></span><span class="row-tag">{{ item.tag || '复习' }}</span></button></article>
          <article class="recommendation-panel"><div class="panel-heading"><div><span class="panel-icon new">新</span><div><h3>学习推荐</h3><p>向前一步，打开一首新诗</p></div></div><button @click="$router.push('/search')">去探索 ↗</button></div><div v-if="learnLoading" class="panel-state">AI 正在为你挑选下一首...</div><div v-else-if="learnItems.length === 0" class="panel-state">完成今日学习后，这里会出现更合适的推荐。</div><button v-for="(item, index) in learnItems.slice(0, 3)" :key="item.poem_id || index" class="recommend-row" @click="item.poem_id && navigateToDetail(item.poem_id)"><span class="row-index">0{{ index + 1 }}</span><span class="row-copy"><strong>{{ item.title }}</strong><small>{{ item.author || '精选诗词' }} · {{ item.reason || '与你当前的学习路径相衔接' }}</small></span><span class="row-tag">{{ item.tag || '新读' }}</span></button></article>
        </div>

        <div class="analysis-strip"><div class="analysis-head"><div><span class="panel-icon report">析</span><div><h3>AI 学习分析报告</h3><p>{{ analysis ? '基于最近学习记录，给你一份轻量反馈' : '完成一些练习后，AI 会开始认识你的学习方式' }}</p></div></div><button v-if="analysis" class="refresh-button" title="重新生成报告" @click="refreshAnalysis">刷新报告</button></div><div v-if="analysisLoading" class="analysis-loading">正在分析你的阅读、练习与错题数据...</div><div v-else-if="analysis" class="analysis-body"><p class="analysis-summary">{{ analysis.summary || '你的学习正在形成稳定节奏，继续保持每天一点点的输入。' }}</p><div class="analysis-stats"><div v-for="item in getDataOverviewItems()" :key="item.label"><strong>{{ item.value }}</strong><span>{{ item.label }}</span></div></div><div class="analysis-notes"><div><span>优势</span><p>{{ firstInsight(analysis.strength, '你正在建立自己的诗词阅读节奏。') }}</p></div><div><span>下一步</span><p>{{ firstInsight(analysis.suggestion, '先复习一首，再挑战一道题。') }}</p></div></div></div><div v-else class="analysis-empty"><span>✦</span><p>先完成一段阅读或一次练习，我会据此给你更贴合的建议。</p><button class="text-action" @click="$router.push('/challenge')">去完成一次练习 ↗</button></div></div>
      </div>
    </div>
  </section>
</template>

<script>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
import api from '@/services/api'

export default {
  name: 'AIPersonalizedSection',
  setup() {
    const router = useRouter(); const userStore = useUserStore(); const error = ref(''); const reviewItems = ref([]); const learnItems = ref([]); const analysis = ref(null); const reviewLoading = ref(false); const learnLoading = ref(false); const analysisLoading = ref(false)
    const getGreetingText = () => { const hour = new Date().getHours(); if (hour < 9) return '早上好'; if (hour < 14) return '午安'; if (hour < 18) return '下午好'; return '晚上好' }
    const fetchReview = async () => { reviewLoading.value = true; try { const result = await api.personalized.getReviewRecommendations(); reviewItems.value = result?.success ? result.data || [] : [] } catch { reviewItems.value = [] } finally { reviewLoading.value = false } }
    const fetchLearn = async () => { learnLoading.value = true; try { const result = await api.personalized.getLearnRecommendations(); learnItems.value = result?.success ? result.data || [] : [] } catch { learnItems.value = [] } finally { learnLoading.value = false } }
    const fetchAnalysis = async (force = false) => { analysisLoading.value = true; try { const result = await api.personalized.getAIAnalysis(force); analysis.value = result?.success ? result.data || null : null } catch { analysis.value = null } finally { analysisLoading.value = false } }
    const fetchData = async () => { if (!userStore.isLoggedIn) return; error.value = ''; await Promise.all([fetchReview(), fetchLearn(), fetchAnalysis()]) }
    const refreshAnalysis = () => fetchAnalysis(true)
    const navigateToDetail = (id) => { if (id) router.push(`/poem/${id}`) }
    const getDataOverviewItems = () => { const stats = analysis.value?.stats; if (!stats) return []; return [{ value: stats.total_learned || 0, label: '已学诗词' }, { value: stats.average_score || 0, label: '平均得分' }, { value: `${stats.mastery_rate || 0}%`, label: '掌握率' }, { value: stats.total_recite_attempts || 0, label: '练习次数' }] }
    const firstInsight = (items, fallback) => Array.isArray(items) && items.length ? items[0] : fallback
    const nextAction = computed(() => { const first = reviewItems.value[0] || learnItems.value[0]; if (first) return { title: first.title, reason: first.reason || '这是根据你的学习记录挑出的下一步。', action: reviewItems.value[0] ? '先复习它' : '开始阅读', poemId: first.poem_id, path: '/daily' }; return { title: '先读完今日学习重点', reason: '完成这一小步后，我会更了解你的阅读节奏，给出更准确的建议。', action: '回到今日学习', path: '/' } })
    onMounted(async () => { await userStore.initUser(); if (userStore.isLoggedIn) fetchData() }); watch(() => userStore.isLoggedIn, (value) => { if (value) fetchData(); else { reviewItems.value = []; learnItems.value = []; analysis.value = null } })
    return { userStore, error, reviewItems, learnItems, analysis, reviewLoading, learnLoading, analysisLoading, fetchData, refreshAnalysis, navigateToDetail, getGreetingText, getDataOverviewItems, firstInsight, nextAction }
  }
}
</script>

<style scoped>
