deg,rgba(221,240,231,.8),rgba(255,255,255,.52))}.brief-copy{min-width:0}.brief-label{display:block;margin-bottom:7px;color:#2f8a7b;font:600 11px var(--font-sans)}.recommendation-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.recommendation-panel,.analysis-strip{padding:24px;border:1px solid rgba(51,103,94,.14);border-radius:18px;background:rgba(255,255,255,.49)}.panel-heading,.analysis-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:17px}.panel-heading>div,.analysis-head>div{display:flex;align-items:center;gap:11px}.panel-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#dff0e8;color:#164b48;font:16px var(--font-ancient)}.panel-icon.new{background:#f4ead8;color:#946d36}.panel-icon.report{background:#e2ebf1;color:#466c7c}.panel-heading h3,.analysis-head h3{margin:0;color:#164b48;font:600 18px var(--font-ancient)}.panel-heading p,.analysis-head p{margin:3px 0 0;color:#7a8c87;font:11px var(--font-sans)}.panel-heading button,.refresh-button{padding:4px 0;border:0;background:transparent;color:#2f8a7b;font:600 11px var(--font-sans)}.panel-state{padding:19px 0;color:#879a94;font:12px var(--font-sans)}.recommend-row{display:grid;grid-template-columns:24px 1fr auto;align-items:center;gap:10px;width:100%;padding:12px 0;border:0;border-top:1px solid rgba(51,103,94,.1);background:transparent;text-align:left}.row-index{color:#8ca59b;font:11px var(--font-sans)}.row-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.row-copy strong{overflow:hidden;color:#213534;font:600 15px var(--font-ancient);text-overflow:ellipsis;white-space:nowrap}.row-copy small{overflow:hidden;color:#788a85;font:11px var(--font-sans);text-overflow:ellipsis;white-space:nowrap}.row-tag{padding:4px 6px;border-radius:5px;background:#edf5f0;color:#2f8a7b;font:10px var(--font-sans)}.analysis-strip{background:rgba(247,249,245,.7)}.analysis-head{margin-bottom:20px}.analysis-loading,.analysis-empty{padding:16px 0;color:#7b8d88;font:12px var(--font-sans)}.analysis-empty{display:flex;align-items:center;gap:10px}.analysis-empty>span{color:#c09253;font-size:20px}.analysis-empty p{margin:0}.text-action{margin-left:auto;padding:0;border:0;background:transparent;color:#2f8a7b;font:600 12px var(--font-sans)}.analysis-body{display:grid;grid-template-columns:minmax(0,1fr) 1.05fr;gap:28px;align-items:start}.analysis-summary{margin:0;color:#45645d;font:18px/1.7 var(--font-ancient)}.analysis-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.analysis-stats div{padding-left:12px;border-left:1px solid rgba(47,138,123,.2)}.analysis-stats strong{display:block;color:#164b48;font:600 22px var(--font-sans)}.analysis-stats span{display:block;margin-top:5px;color:#82928d;font:10px var(--font-sans)}.analysis-notes{display:grid;grid-template-columns:1fr 1fr;grid-column:1/-1;gap:20px;margin-top:4px}.analysis-notes div{padding-top:12px;border-top:1px solid rgba(51,103,94,.12)}.analysis-notes span{color:#2f8a7b;font:600 11px var(--font-sans)}.analysis-notes p{margin:7px 0 0;color:#6d817d;font:12px/1.6 var(--font-sans)}
@media (max-width:760px){.ai-personalized-section{padding:58px 14px 8px}.ai-heading{display:block}.ai-badge{display:inline-block;margin-top:15px}.ai-login-state,.assistant-brief{align-items:flex-start;flex-wrap:wrap;padding:20px}.ai-button{margin-left:auto}.recommendation-grid,.analysis-body{grid-template-columns:1fr}.analysis-stats{gap:9px}.analysis-summary{font-size:16px}.analysis-notes{grid-template-columns:1fr;gap:12px}}
</style>
